/// Scope for dns deterministic name hash calculation.
enum AutoGeneratedDomainNameLabelScope {
  valueTenantReuse("TenantReuse");

  const AutoGeneratedDomainNameLabelScope(this.wireValue);
  final String wireValue;

  static AutoGeneratedDomainNameLabelScope fromValue(String value) {
    for (final item in AutoGeneratedDomainNameLabelScope.values) {
      if (item.wireValue == value) {
        return item;
      }
    }
    throw ArgumentError(
      'Unknown AutoGeneratedDomainNameLabelScope value: $value',
    );
  }
}
